CREATE TABLE IF NOT EXISTS account(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,secret TEXT NOT NULL,demo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS session(token TEXT PRIMARY KEY, owner INTEGER NOT NULL REFERENCES account(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payer(id INTEGER PRIMARY KEY,owner INTEGER NOT NULL REFERENCES account(id),name TEXT NOT NULL,kind TEXT NOT NULL,days INTEGER NOT NULL,terms TEXT NOT NULL,UNIQUE(owner,id),UNIQUE(owner,kind,name));
CREATE TABLE IF NOT EXISTS movement(id INTEGER PRIMARY KEY,owner INTEGER NOT NULL REFERENCES account(id),kind TEXT NOT NULL,source TEXT NOT NULL,concept TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0), day TEXT NOT NULL,due TEXT,payer INTEGER,reference TEXT,void INTEGER NOT NULL DEFAULT 0, recurrence INTEGER NOT NULL DEFAULT 0, series INTEGER, UNIQUE(owner,id),UNIQUE(owner,series,day),FOREIGN KEY(owner,payer) REFERENCES payer(owner,id));
CREATE TABLE IF NOT EXISTS settlement(id INTEGER PRIMARY KEY,owner INTEGER NOT NULL,movement INTEGER NOT NULL,day TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),reason TEXT NOT NULL,FOREIGN KEY(owner,movement) REFERENCES movement(owner,id));
CREATE TABLE IF NOT EXISTS reminder(id INTEGER PRIMARY KEY,owner INTEGER NOT NULL,movement INTEGER NOT NULL,day TEXT NOT NULL,note TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(owner,movement) REFERENCES movement(owner,id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,owner INTEGER NOT NULL REFERENCES account(id),action TEXT NOT NULL,details TEXT NOT NULL,created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS request(owner INTEGER NOT NULL REFERENCES account(id),key TEXT NOT NULL,PRIMARY KEY(owner,key));
CREATE TABLE IF NOT EXISTS recovery(owner INTEGER PRIMARY KEY REFERENCES account(id), digest TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_attempt(bucket TEXT PRIMARY KEY, started INTEGER NOT NULL, attempts INTEGER NOT NULL);
